INSERT INTO kn_pages (lang, slug, title, template, status, content, meta_title, meta_description, robots, sort_order)
SELECT 'fr', 'nettoyage-voiture-interieur-exterieur', 'Nettoyage voiture intérieur et extérieur', 'page', 'draft', '[{"type":"hero","bg":"cream","layout":"1-1","visual_type":"photo","eyebrow":"NOS PRESTATIONS AUTO","h1":"Nettoyage voiture intérieur et extérieur à domicile : toutes nos formules en détail","body":"Une voiture propre dedans comme dehors, sans quitter votre domicile ni votre lieu de travail. Comparez nos quatre formules, repérez celle qui correspond à l\'état de votre véhicule et réservez en quelques minutes.","cta_eyebrow":"COMPARER LES FORMULES","cta_title":"Voir le comparatif","cta_url":"#comparatif","pills":[{"icon":"star","text":"4,9/5 · +159 avis","style":"white"},{"icon":"shield","text":"Paiement après la prestation","style":"rose"},{"icon":"home","text":"À domicile ou en atelier","style":"night"}],"visible":["desktop","tablet","mobile"]},{"type":"html","html":"<section class=\\"kn-section kn-bg--white kn-jump-wrap\\"><div class=\\"container\\"><p class=\\"kn-jump__title\\">Aller directement à</p><nav class=\\"kn-jump\\" aria-label=\\"Navigation de la page\\"><a href=\\"#comparatif\\">Comparatif</a><a href=\\"#shampoing-sieges\\">Shampoing des sièges</a><a href=\\"#interieur-exterieur\\">Intérieur &amp; Extérieur</a><a href=\\"#remise-a-neuf-interieur\\">Remise à neuf intérieur</a><a href=\\"#remise-a-neuf-complete\\">Remise à neuf complète</a><a href=\\"#ozone\\">Option ozone</a><a href=\\"#choisir\\">Choisir sa formule</a><a href=\\"#faq\\">Questions fréquentes</a></nav></div></section>","visible":["desktop","tablet","mobile"]},{"type":"text","bg":"white","html":"<h2 class=\\"kn-subtitle\\">Un véhicule aussi propre à l\'intérieur qu\'à l\'extérieur</h2><p>Une voiture se salit de deux façons : par l\'extérieur (boue, insectes, pollution, sel de route) et par l\'intérieur (poussière, miettes, taches de boisson, traces de pieds et de mains, odeurs). Deux types de salissures, deux types de traitements : c\'est pourquoi nous proposons quatre formules, du simple coup de frais aux grandes remises à neuf.</p><p>Un nettoyage professionnel apporte du confort au quotidien, un habitacle plus sain pour les passagers, et un véhicule mieux présenté le jour de la revente ou de la restitution d\'un leasing. Cette page détaille ce que comprend chaque formule, pour quelle situation elle est pensée, et comment faire le bon choix. Tous les prix indiqués sont des tarifs « à partir de » pour une citadine ; le montant exact dépend du véhicule et du lieu d\'intervention.</p>","visible":["desktop","tablet","mobile"]},{"type":"html","html":"<section class=\\"kn-section kn-bg--alt kn-compare\\" id=\\"comparatif\\"><div class=\\"container\\"><header class=\\"kn-compare__head\\"><span class=\\"kn-eyebrow\\">COMPARATIF</span><h2 class=\\"kn-section__title\\">Comparer les formules en un coup d\'œil</h2></header><div class=\\"kn-compare__scroll\\"><table><thead><tr><th scope=\\"col\\">Formule</th><th scope=\\"col\\">Shampoing des sièges</th><th scope=\\"col\\">Intérieur &amp; Extérieur<small>Le plus demandé</small></th><th scope=\\"col\\">Remise à neuf intérieur</th><th scope=\\"col\\">Remise à neuf complète<small>Idéal fin de leasing</small></th></tr></thead><tbody><tr><th scope=\\"row\\">Prix dès</th><td class=\\"is-price\\">80 €</td><td class=\\"is-price\\">95 €</td><td class=\\"is-price\\">180 €</td><td class=\\"is-price\\">240 €</td></tr><tr><th scope=\\"row\\">Durée indicative</th><td>≈ 1 h</td><td>≈ 1 h 30</td><td>Selon l&#039;état du véhicule</td><td>Jusqu&#039;à ≈ 4 h</td></tr><tr><th scope=\\"row\\">Sièges</th><td>Aspiration + shampoing</td><td>Aspiration</td><td>Shampoing, cuirs et carpettes</td><td>Shampoing, cuirs et carpettes</td></tr><tr><th scope=\\"row\\">Habitacle</th><td class=\\"is-no\\">—</td><td>Aspiration complète, plastiques, vitres</td><td>Nettoyage complet, vitres et pare-brise, volant dégraissé</td><td>Nettoyage complet, vitres et pare-brise, volant dégraissé</td></tr><tr><th scope=\\"row\\">Extérieur</th><td class=\\"is-no\\">—</td><td>Lavage manuel, jantes, brillant pneus, hydrophobe</td><td class=\\"is-no\\">—</td><td>Lavage complet, plastiques extérieurs, hydrophobe</td></tr><tr><th scope=\\"row\\">Finition</th><td>Parfum longue durée</td><td>Parfum d&#039;ambiance</td><td>Parfum longue durée</td><td>Parfum longue durée</td></tr><tr><th scope=\\"row\\">Idéal pour</th><td>Sièges tachés</td><td>Entretien régulier</td><td>Intérieur très marqué</td><td>Fin de leasing, revente</td></tr></tbody></table></div><p class=\\"kn-compare__note\\">Prix « à partir de » pour une citadine. Option ozone disponible avec toutes les formules.</p><div class=\\"kn-compare__cta\\"><a class=\\"kn-btn\\" href=\\"/nettoyage-voiture-domicile\\">Calculer le tarif pour mon véhicule</a></div></div></section>","visible":["desktop","tablet","mobile"]},{"type":"html","html":"<span id=\\"shampoing-sieges\\" class=\\"kn-anchor\\"></span>","visible":["desktop","tablet","mobile"]},{"type":"prestation","bg":"white","eyebrow":"FORMULE 1 · NOUVEAU","h2":"Shampoing des sièges : retrouver des assises propres","intro":"Les sièges concentrent l\'essentiel des taches d\'un habitacle : café renversé, traces d\'enfants, transpiration, poils d\'animaux. Cette formule se concentre sur eux, sans le reste, pour un résultat net à petit prix.","metas":[{"icon":"zap","label":"À partir de","value":"80 €"},{"icon":"clock","label":"Durée","value":"≈ 1 h"}],"columns":"1","list_title":"Ce que nous faisons","items":[{"title":"Aspiration des sièges","desc":"On retire d\'abord la poussière et les miettes logées dans les coutures."},{"title":"Shampoing des sièges","desc":"Un nettoyage en profondeur qui extrait la saleté des fibres et estompe les taches."},{"title":"Parfum longue durée","desc":"Une touche de fraîcheur pour finir."}],"note":"Le shampoing des carpettes est possible en supplément. L\'intérieur et l\'extérieur ne sont pas compris dans cette formule.","cta_label":"Réserver le shampoing des sièges","cta_url":"/nettoyage-voiture-domicile","visible":["desktop","tablet","mobile"]},{"type":"html","html":"<span id=\\"interieur-exterieur\\" class=\\"kn-anchor\\"></span>","visible":["desktop","tablet","mobile"]},{"type":"prestation","bg":"cream","eyebrow":"FORMULE 2 · LE PLUS DEMANDÉ","h2":"Intérieur & Extérieur : l\'entretien complet","intro":"C\'est la formule des voitures déjà suivies : on rafraîchit l\'habitacle et on lave la carrosserie à la main. Elle convient très bien à un entretien régulier, tous les deux à trois mois, pour que la saleté n\'ait jamais le temps de s\'incruster.","metas":[{"icon":"zap","label":"À partir de","value":"95 €"},{"icon":"clock","label":"Durée","value":"≈ 1 h 30"}],"columns":"2","list_title":"Ce que nous faisons","items":[{"title":"Habitacle dépoussiéré et aspiré","desc":"Tableau de bord, console, contre-portes et sols, sans oublier le coffre."},{"title":"Plastiques intérieurs traités","desc":"Un entretien léger qui redonne un aspect propre et net."},{"title":"Vitres intérieures sans traces","desc":"Une visibilité parfaite, même à contre-jour."},{"title":"Prélavage à la mousse active","desc":"La saleté est décollée avant tout contact, pour protéger la peinture."},{"title":"Lavage manuel et séchage","desc":"Un lavage délicat, puis un séchage complet y compris les seuils de portes."},{"title":"Jantes, passages de roues, pneus","desc":"Nettoyage des jantes et des passages de roues, brillant sur les pneus."},{"title":"Protection hydrophobe","desc":"L\'eau perle sur la carrosserie et la saleté s\'accroche moins."},{"title":"Parfum d\'ambiance","desc":"Une fraîcheur légère à l\'intérieur."}],"cta_label":"Réserver cette formule","cta_url":"/nettoyage-voiture-domicile","visible":["desktop","tablet","mobile"]},{"type":"html","html":"<span id=\\"remise-a-neuf-interieur\\" class=\\"kn-anchor\\"></span>","visible":["desktop","tablet","mobile"]},{"type":"prestation","bg":"white","eyebrow":"FORMULE 3","h2":"Remise à neuf intérieur : un habitacle comme neuf","intro":"Pour un intérieur très marqué (enfants, animaux, usage intensif, voiture achetée d\'occasion), l\'entretien ne suffit plus. La remise à neuf intérieur reprend tout l\'habitacle en profondeur : elle reprend les soins de la formule Intérieur & Extérieur côté intérieur, et y ajoute les shampoings et le traitement des cuirs. L\'extérieur n\'en fait pas partie.","metas":[{"icon":"zap","label":"À partir de","value":"180 €"},{"icon":"clock","label":"Durée","value":"Selon l\'état"}],"columns":"2","list_title":"Ce que nous ajoutons à l\'entretien","items":[{"title":"Shampoing des sièges","desc":"Un nettoyage en profondeur de toutes les assises."},{"title":"Nettoyage des cuirs","desc":"Un soin adapté pour nettoyer sans dessécher la matière."},{"title":"Shampoing des carpettes","desc":"Fini les traces de pas incrustées."},{"title":"Habitacle nettoyé intégralement","desc":"Toutes les surfaces, du tableau de bord aux contre-portes."},{"title":"Vitres et pare-brise","desc":"Un verre net, sans voile ni traces."},{"title":"Volant dégraissé","desc":"La pièce que l\'on touche le plus, enfin propre."},{"title":"Parfum longue durée","desc":"Une fraîcheur qui reste dans le temps."}],"note":"Les odeurs tenaces se traitent avec l\'option ozone.","cta_label":"Réserver la remise à neuf intérieure","cta_url":"/nettoyage-voiture-domicile","visible":["desktop","tablet","mobile"]},{"type":"html","html":"<span id=\\"remise-a-neuf-complete\\" class=\\"kn-anchor\\"></span>","visible":["desktop","tablet","mobile"]},{"type":"prestation","bg":"cream","eyebrow":"FORMULE 4 · IDÉAL FIN DE LEASING","h2":"Remise à neuf complète : la formule fin de leasing","intro":"C\'est la plus complète : la remise à neuf intérieure, plus un traitement extérieur approfondi. Elle est pensée pour les moments où l\'état de la voiture compte vraiment : restitution d\'un leasing, mise en vente, livraison à un nouveau propriétaire. Il est conseillé de la réserver deux à quatre semaines avant l\'échéance.","metas":[{"icon":"zap","label":"À partir de","value":"240 €"},{"icon":"clock","label":"Durée","value":"Jusqu\'à ≈ 4 h"}],"columns":"2","list_title":"Ce que nous faisons","items":[{"title":"Toute la remise à neuf intérieure","desc":"Sièges, cuirs, carpettes, habitacle, vitres, volant et parfum longue durée."},{"title":"Prélavage et lavage manuel","desc":"Mousse active puis lavage délicat de la carrosserie."},{"title":"Jantes et passages de roues","desc":"Nettoyés en détail, avec brillant sur les pneus."},{"title":"Plastiques extérieurs traités","desc":"Les plastiques ternes retrouvent de la profondeur."},{"title":"Séchage complet","desc":"Y compris les seuils de portes."},{"title":"Protection hydrophobe","desc":"Une carrosserie qui reste propre plus longtemps."}],"note":"Pour préparer sa restitution, lisez notre article sur le nettoyage de fin de leasing et d\'avant vente.","cta_label":"Réserver la remise à neuf complète","cta_url":"/nettoyage-voiture-domicile","visible":["desktop","tablet","mobile"]},{"type":"html","html":"<span id=\\"ozone\\" class=\\"kn-anchor\\"></span>","visible":["desktop","tablet","mobile"]},{"type":"domicile-vs-atelier","bg":"white","eyebrow":"EN COMPLÉMENT","h2":"Option ozone et conditions d\'intervention","home_title":"Option ozone : en finir avec les odeurs","home_icon":"wind","home_desc":"Tabac, animaux, humidité, nourriture oubliée : certaines odeurs s\'incrustent dans les textiles et la ventilation. L\'ozone les neutralise à la source plutôt que de les masquer.","home_items":[{"icon":"check","label":"Compatible avec toutes les formules"},{"icon":"check","label":"Utile après un tabagisme ou des animaux"},{"icon":"check","label":"Tarif sur demande, selon le véhicule"}],"home_cta_eyebrow":"ODEURS TENACES","home_cta_title":"Demander l\'option ozone","home_cta_url":"#contact","workshop_title":"Ce qu\'il faut prévoir","workshop_icon":"check-big","workshop_desc":"Pour une intervention à domicile, quelques conditions simples :","workshop_items":[{"icon":"check","label":"Un accès à l\'eau (robinet extérieur ou tuyau)"},{"icon":"check","label":"Une prise électrique à proximité"},{"icon":"check","label":"Un véhicule accessible, sans effets personnels de valeur"},{"icon":"check","label":"Déplacement gratuit dans un rayon de 20 km autour de Seraing, puis 0,50 € par km supplémentaire"}],"workshop_note":"Les prix varient selon l\'état et le type de véhicule.","visible":["desktop","tablet","mobile"]},{"type":"html","html":"<span id=\\"choisir\\" class=\\"kn-anchor\\"></span>","visible":["desktop","tablet","mobile"]},{"type":"how","bg":"alt","columns":"4","eyebrow":"BIEN CHOISIR","h2":"Comment choisir votre formule","steps":[{"num":"A","title":"Voiture suivie, entretien régulier","body":"Intérieur & Extérieur, tous les deux à trois mois."},{"num":"B","title":"Sièges tachés, reste correct","body":"Shampoing des sièges : la solution ciblée."},{"num":"C","title":"Intérieur très marqué","body":"Remise à neuf intérieur pour tout reprendre en profondeur."},{"num":"D","title":"Revente ou fin de leasing","body":"Remise à neuf complète, 2 à 4 semaines avant l\'échéance."}],"visible":["desktop","tablet","mobile"]},{"type":"seo-content","bg":"rose","h2":"À domicile, au travail ou à l\'atelier de Visé ?","body":"<p>La qualité du nettoyage est la même partout : seule la logistique change. À domicile ou sur votre lieu de travail, vous ne vous déplacez pas. À l\'atelier de Visé (province de Liège), le tarif est plus avantageux, vous disposez d\'un espace d\'attente et vous pouvez ajouter un polissage ou un traitement céramique.</p><p><a href=\\"/nettoyage-voiture-domicile\\">Voir le tarif exact pour votre véhicule et votre lieu d\'intervention</a> · <a href=\\"/polissage-voiture-liege\\">Découvrir le polissage et la céramique</a></p>","cta_label":"Prendre RDV en ligne","cta_style":"primary","cta_align":"left","visible":["desktop","tablet","mobile"]},{"type":"seo-content","bg":"white","h2":"Voitures de société, flottes et abonnement","body":"<p>Pour les professionnels, nous nettoyons les véhicules de fonction et les utilitaires, y compris sur le lieu de travail de vos collaborateurs. Cette dépense est jusqu\'à 100 % déductible selon votre situation fiscale. Pour un entretien régulier, un abonnement permet de bénéficier de remises dégressives selon la durée d\'engagement.</p><p><a href=\\"/offre-professionnelle-de-nettoyage-voiture-entreprises-independants\\">Découvrir l\'offre entreprises et indépendants</a></p><p><strong>Carte de fidélité :</strong> à chaque nettoyage, vous cumulez des étoiles et faites des économies sur les suivants.</p>","cta_label":"Demander une offre sur mesure","cta_url":"#contact","cta_style":"outline","cta_align":"left","visible":["desktop","tablet","mobile"]},{"type":"html","html":"<span id=\\"faq\\" class=\\"kn-anchor\\"></span>","visible":["desktop","tablet","mobile"]},{"type":"accordion","bg":"alt","eyebrow":"FAQ","h2":"Vos questions sur nos formules de nettoyage auto","items":[{"q":"Quelle formule choisir si je ne sais pas ?","a":"Si la voiture est globalement propre, l\'Intérieur & Extérieur suffit. Si l\'habitacle est très marqué, partez sur une remise à neuf intérieure. Une photo ou un échange rapide avec notre équipe permet de trancher."},{"q":"Quelle différence entre Intérieur & Extérieur et une remise à neuf ?","a":"L\'Intérieur & Extérieur est un entretien : aspiration, dépoussiérage et lavage manuel. La remise à neuf va plus loin sur l\'intérieur, avec le shampoing des sièges et des carpettes, le soin des cuirs et le volant dégraissé."},{"q":"La remise à neuf intérieure comprend-elle le lavage de la carrosserie ?","a":"Non, elle se concentre sur l\'habitacle. Pour traiter aussi l\'extérieur, choisissez la remise à neuf complète."},{"q":"À quoi sert l\'option ozone ?","a":"Elle neutralise les odeurs tenaces (tabac, animaux, humidité) à la source. Elle s\'ajoute à n\'importe quelle formule et se chiffre sur demande."},{"q":"Dois-je vider ma voiture avant le passage ?","a":"C\'est préférable : retirez les effets personnels, les sièges enfants et les objets de valeur. Cela facilite l\'accès à toutes les surfaces."},{"q":"Mon véhicule est très sale ou plein de poils d\'animaux, est-ce un problème ?","a":"Non, mais prévoyez plutôt une remise à neuf, plus adaptée. Précisez l\'état du véhicule lors de la réservation pour que nous prévoyions le temps nécessaire."},{"q":"À quelle fréquence nettoyer sa voiture ?","a":"Tous les deux à trois mois pour un usage normal, plus souvent avec enfants, animaux ou trajets quotidiens. Une remise à neuf annuelle complète le suivi."},{"q":"Les prix affichés sont-ils définitifs ?","a":"Ce sont des tarifs « à partir de » pour une citadine. Le montant exact dépend du type de véhicule, de son état et du lieu d\'intervention : vous le voyez avant de confirmer dans le simulateur de prix."}],"visible":["desktop","tablet","mobile"]},{"type":"contact","bg":"white","eyebrow":"BESOIN D\'UN CONSEIL ?","h2":"Besoin d\'un conseil pour choisir votre formule ?","intro":"Décrivez-nous votre véhicule et son état : nous vous recommandons la formule la plus adaptée, sans engagement.","subjects":"Conseil pour choisir une formule\\nDevis véhicule utilitaire\\nOption ozone\\nUne question","whatsapp_text":"Bonjour, je souhaite un conseil pour le nettoyage de ma voiture.","visible":["desktop","tablet","mobile"]},{"type":"reviews","bg":"cream","eyebrow":"ILS NOUS FONT CONFIANCE","h2":"Ce que disent nos clients","visible":["desktop","tablet","mobile"]},{"type":"cta-final","bg":"blue","eyebrow":"RÉSERVATION EN LIGNE","title":"Prêt à retrouver une voiture <span class=\\"hl-inverse\\">impeccable</span> ?","cta_title":"Prenez RDV en ligne","phone":"+32 (0)4 55 13 84 19","visible":["desktop","tablet","mobile"]}]', 'Nettoyage voiture intérieur et extérieur : formules | Keepnew', 'Shampoing des sièges, intérieur & extérieur, remise à neuf : comparez nos formules de nettoyage auto à domicile (Liège, Namur) et réservez en ligne.', 'index,follow', 0
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM kn_pages WHERE slug = 'nettoyage-voiture-interieur-exterieur' AND lang = 'fr');
